    int f(int x) {
        return 3*x*x - 2;
    }

    int g(int x) {
        return x*x + x + 1;
    }

    int g_of_f_of_25 = g(f(25));
    int sum_of_g_of_f_of_25 = 0;

    for (int i = 0; i <= 100; i++) {
        sum_of_g_of_f_of_25 += g_of_f_of_25;
    }

    std::cout << "The sum of all possible values of g(25) is " << sum_of_g_of_f_of_25 << std::endl;

    return 0;
}

