Let $A = (-3, 0),$ $B=(-2,1),$ $C=(2,1),$ and $D=(3,0).$ Suppose that point $P$ satisfies \[PA + PD = PB + PC = 8.\]Then the $y-$coordinate of $P,$ when simplified, can be expressed in the form $\frac{-a + b \sqrt{c}}{d},$ where $a,$ $b,$ $c,$ $d$ are positive integers.  Find $a + b + c + d.$

Put your final answer within \boxed{}.

#include <iostream>
#include <cmath>
using namespace std;

int main() {
    double x1 = -3, y1 = 0;
    double x2 = -2, y2 = 1;
    double x3 = 2, y3 = 1;
    double x4 = 3, y4 = 0;

    double xP, yP;

    double PA = sqrt(pow(xP - x1, 2) + pow(yP - y1, 2));
    double PB = sqrt(pow(xP - x2, 2) + pow(yP - y2, 2));
    double PC = sqrt(pow(xP - x3, 2) + pow(yP - y3, 2));
    double PD = sqrt(pow(xP - x4, 2) + pow(yP - y4, 2));

    yP = (8 - PA - PD + PB + PC) / 2;

    int a = round(yP);
    int b = round(sqrt(pow(yP, 2) - pow(a, 2)));
    int c = round(pow(yP, 2) - pow(a, 2));
    int d = round(yP);

    cout << a + b + c + d << endl;

    return 0;
}

